// Servo radar: servo döner, HC-SR04 her açıda mesafeyi ölçer, seri ekrana "aci,mesafe" yazar.
#include <Servo.h>  // Arduino IDE ile gelir

const int SERVO_PIN = 9;
const int TRIG_PIN = 12;
const int ECHO_PIN = 11;
const int BUZZER_PIN = 4;
const int LED_PIN = 6;

const int MIN_ACI = 15;        // taramanın başı
const int MAX_ACI = 165;       // taramanın sonu
const int ADIM = 3;            // her adımda dönülen derece
const int BEKLE_MS = 30;       // servo yerine otursun diye bekleme
const int YAKIN_CM = 30;       // bundan yakın cisim uyarı verir

Servo servo;
int aci = MIN_ACI;
int yon = ADIM;
long enYakinCm = 0;   // bu taramadaki en yakın cisim (0: yok)
int enYakinAci = 0;

// Mesafeyi cm olarak döndürür; yankı gelmezse 0.
long mesafeOlc() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long sure = pulseIn(ECHO_PIN, HIGH, 30000);  // en çok 30 ms bekle (~5 m)
  return sure / 58;
}

// Bir tarama bitince en yakın cismi yazar ve sayacı sıfırlar.
void taramaBitti() {
  Serial.print("# En yakin: ");
  if (enYakinCm > 0) {
    Serial.print(enYakinCm);
    Serial.print(" cm, aci ");
    Serial.println(enYakinAci);
  } else {
    Serial.println("yok");
  }
  enYakinCm = 0;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(LED_PIN, OUTPUT);
  servo.attach(SERVO_PIN);
  servo.write(aci);
  delay(500);
  Serial.println("# Radar basladi. Bicim: aci,mesafe");
}

void loop() {
  servo.write(aci);
  delay(BEKLE_MS);
  long cm = mesafeOlc();

  Serial.print(aci);
  Serial.print(',');
  Serial.println(cm);

  if (cm > 0 && (enYakinCm == 0 || cm < enYakinCm)) {
    enYakinCm = cm;
    enYakinAci = aci;
  }

  bool yakin = cm > 0 && cm < YAKIN_CM;
  digitalWrite(LED_PIN, yakin ? HIGH : LOW);
  if (yakin) tone(BUZZER_PIN, 2000, 20);

  // Uca gelince yön değiştir.
  aci += yon;
  if (aci >= MAX_ACI) {
    aci = MAX_ACI;
    yon = -ADIM;
    taramaBitti();
  } else if (aci <= MIN_ACI) {
    aci = MIN_ACI;
    yon = ADIM;
    taramaBitti();
  }
}
